import{_ as a,H as s,f as i,i as t}from"./chunks/framework.BH2BK_3i.js";const u=JSON.parse('{"title":"41 | 线上综合案例：节约线上千台容器的性能分析实战","description":"","frontmatter":{},"headers":[{"level":2,"title":"程序问题描述与排查过程","slug":"程序问题描述与排查过程","link":"#程序问题描述与排查过程","children":[{"level":3,"title":"请求排队问题","slug":"请求排队问题","link":"#请求排队问题","children":[]},{"level":3,"title":"程序随着时间状态恶化问题","slug":"程序随着时间状态恶化问题","link":"#程序随着时间状态恶化问题","children":[]},{"level":3,"title":"网络请求处理不过来的问题","slug":"网络请求处理不过来的问题","link":"#网络请求处理不过来的问题","children":[]},{"level":3,"title":"磁盘 IO 和系统调用堵塞问题","slug":"磁盘-io-和系统调用堵塞问题","link":"#磁盘-io-和系统调用堵塞问题","children":[]},{"level":3,"title":"Go 调度器的调度延迟问题","slug":"go-调度器的调度延迟问题","link":"#go-调度器的调度延迟问题","children":[]},{"level":3,"title":"请求消耗过多 CPU 的问题","slug":"请求消耗过多-cpu-的问题","link":"#请求消耗过多-cpu-的问题","children":[]},{"level":3,"title":"并发导致的锁问题","slug":"并发导致的锁问题","link":"#并发导致的锁问题","children":[]},{"level":3,"title":"同步写日志的磁盘问题","slug":"同步写日志的磁盘问题","link":"#同步写日志的磁盘问题","children":[]},{"level":3,"title":"垃圾回收问题","slug":"垃圾回收问题","link":"#垃圾回收问题","children":[]},{"level":3,"title":"宿主机问题","slug":"宿主机问题","link":"#宿主机问题","children":[]},{"level":3,"title":"“以退为进分析法”","slug":"以退为进分析法","link":"#以退为进分析法","children":[]}]},{"level":2,"title":"进一步分析与修复问题","slug":"进一步分析与修复问题","link":"#进一步分析与修复问题","children":[]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"课后题","slug":"课后题","link":"#课后题","children":[]}],"relativePath":"Go进阶·分布式爬虫实战/41｜线上综合案例：节约线上千台容器的性能分析实战.md","filePath":"Go进阶·分布式爬虫实战/41｜线上综合案例：节约线上千台容器的性能分析实战.md","lastUpdated":1795487521000}'),p={name:"Go进阶·分布式爬虫实战/41｜线上综合案例：节约线上千台容器的性能分析实战.md"};function l(n,e,o,h,r,c){return s(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="_41-线上综合案例-节约线上千台容器的性能分析实战" tabindex="-1">41 | 线上综合案例：节约线上千台容器的性能分析实战 <a class="header-anchor" href="#_41-线上综合案例-节约线上千台容器的性能分析实战" aria-label="Permalink to &quot;41 | 线上综合案例：节约线上千台容器的性能分析实战&quot;">​</a></h1><p>你好，我是郑建勋。</p><p>当我们对 Go 程序进行性能分析时，一般想到的方式是使用 pprof 提供的一系列工具分析 CPU火焰图、内存占用情况等。</p><p>诚然，通过分析 CPU 耗时最多的流程，设法对 CPU 耗时最多的函数进行优化，毫无疑问能够改善程序整体的状况。然而，优化了这些步骤就一定能够大幅度提高容器的 QPS，降低机器数量，一定能够大幅度提高性能吗？</p><p>不一定。因为一个函数在 pprof 中耗时多，可能是因为它本身耗时就多，它是现象却不一定是问题。同时，在高负载情况下，可能会导致某一些请求、函数的耗时突然升高，而这些异常却又不一定能够体现在 pprof 上。因为 pprof 能看到整体的耗时情况，却难以分析个例。因此，有时候我们需要跳出 pprof cpu profiling，仔细审视程序遇到的最严重的性能瓶颈。</p><p>这节课，我们一起来回顾分析线上的 Go Web 程序的性能瓶颈的整个过程，看看最终如何节约上千台容器。这节课用到的工具和方法也可以给我们排查其他瓶颈问题一些启发。</p><h2 id="程序问题描述与排查过程" tabindex="-1">程序问题描述与排查过程 <a class="header-anchor" href="#程序问题描述与排查过程" aria-label="Permalink to &quot;程序问题描述与排查过程&quot;">​</a></h2><p>我们团队维护的一个核心程序为 Go Web 服务，当前程序能够承载的 QPS 非常低。当 QPS上涨到一个阈值时，就会出现 p99 抖动，导致接口耗时超过了上游给定的超时时间。在过去，解决这类问题的方法就是加容器来分摊请求量，随着业务发展，时间久了，这个核心服务线上就有了几千台容器。最近几年，很多开发者都尝试分析这个问题的原因，但都无功而返，现在由于有了降本的需求，需要再次直视这个问题。</p><p>为了更精准地分析现状，我们采用了线上压测的方式，通过提高某一台容器权重的方式提高该容器的请求量。经过压测分析，我们得到了下面这些信息。</p><ul><li><p>正常情况下服务约为 3QPS，p99 耗时在 300 毫秒左右（意味着如果有 100 个请求，99 个请求的耗时在 300 毫秒以下），p95 耗时 120 毫秒左右。当压测上涨到 16QPS 以上时，会看到耗时 p99 抖动，而 p95 仍保持稳定。压测时容器 p99 在 700 毫秒以上。</p></li><li><p>cpu idle（CPU 处于空闲状态时间比例）在 80% 以上。</p></li><li><p>内存容量充足，内存利用率 55% 左右。</p></li><li><p>获取耗时异常的请求，并再次调用该请求时，耗时能够恢复正常。每次请求走的是相同的代码路径，但是请求耗时差距可达 300 毫秒以上。</p></li><li><p>程序也会有许多下游的网络调用，而这些下游调用的 p99 耗时稳定，可以大致排除问题出在下游服务的可能。</p></li><li><p>程序占用的内存约为 4G，而且较为稳定。容器 Cgroup 可使用的容量大小为 16G。分析程序暴露的运行时内存分配 Metric，没有发现明显的异常。</p></li><li><p>程序本身协程数量在 120 左右，但是大部分都在休眠状态。在负载情况下，协程数量与请求数量大致相同。协程数量增长到了 130 左右。运行的协程数量是不多的。</p></li><li><p>用如下指令获取线程数量，结果约为 14 个，在压测时并没有增加线程数量。</p></li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /proc/\`</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ps</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -ef</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xxx </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> awk</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;NR==1 {print $2}&#39;\`</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/status</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Threads</span></span></code></pre></div><ul><li>当容器飘逸到性能更强的宿主机后，耗时能够得到显著缓解。</li></ul><p>综上，我们主要面对的其实是耗时 p99 抖动的问题，下面我们分别对问题进行拆解。</p><h3 id="请求排队问题" tabindex="-1">请求排队问题 <a class="header-anchor" href="#请求排队问题" aria-label="Permalink to &quot;请求排队问题&quot;">​</a></h3><p>首先，耗时上涨可能是 HTTP 请求排队导致的吗？HTTP Keep-Alive 为 true 时会复用连接，第二个请求会等待第一个请求完成，但是这种假设不成立。通过下面的指令，我们发现连接总是在不断变化，没有复用长连接。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>netstat -antp |grep xxx | grep ES</span></span></code></pre></div><p>并且，我们在程序中打印的请求耗时时间，是从接收到请求之后开始计时的，所以耗时还是发生在程序中的。</p><h3 id="程序随着时间状态恶化问题" tabindex="-1">程序随着时间状态恶化问题 <a class="header-anchor" href="#程序随着时间状态恶化问题" aria-label="Permalink to &quot;程序随着时间状态恶化问题&quot;">​</a></h3><p>但是我们新部署的容器，还是会出现这个问题，所以排除掉这个假设。</p><h3 id="网络请求处理不过来的问题" tabindex="-1">网络请求处理不过来的问题 <a class="header-anchor" href="#网络请求处理不过来的问题" aria-label="Permalink to &quot;网络请求处理不过来的问题&quot;">​</a></h3><p>要验证这一假设，我们需要看看 Go 语言中的网络处理模型。对于网络 IO 来说，Go 语言拥有足够优秀的网络模型来处理大量的网络请求。它使用的是封装 epoll 的方式，过程轻量、异步且快速。不会因为某一个协程的网络堵塞导致其他协程排队。同时，观察我们打印的 p99 异常请求的耗时，会发现这些请求的下游网络耗时很正常，并没有堵塞。</p><h3 id="磁盘-io-和系统调用堵塞问题" tabindex="-1">磁盘 IO 和系统调用堵塞问题 <a class="header-anchor" href="#磁盘-io-和系统调用堵塞问题" aria-label="Permalink to &quot;磁盘 IO 和系统调用堵塞问题&quot;">​</a></h3><p>磁盘 IO 和系统调用确实有可能因为堵塞产生排队的问题。但是 Go 语言的 sysmon 监控程序每隔 10 毫秒会监控这种情况并适时地创建新的线程。再加上 Go 调度器的均衡工作，从理论上来讲，程序的理想运行状态应该是，随着负载的增加，耗时稳定上升，不会突然出现的毛刺。</p><h3 id="go-调度器的调度延迟问题" tabindex="-1">Go 调度器的调度延迟问题 <a class="header-anchor" href="#go-调度器的调度延迟问题" aria-label="Permalink to &quot;Go 调度器的调度延迟问题&quot;">​</a></h3><p>实际上，即便在压测时，当前的 QPS 也很低，只有 16QPS 左右。如果任务数增加，Go 运行时调度器进行调度时，某一个协程长期得不到执行的可能性很低。8 个逻辑处理器 P 足够承载当前的 QPS 了。</p><p>我们再进一步分析一下调度器的细节。如下面的启动指令，在程序启动时加入环境变量GODEBUG=schedtrace=1000,scheddetail=1，这时程序每隔一秒就会打印出调度器的细节。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GOMAXPROCS=8 GODEBUG=schedtrace=1000,scheddetail=1 nohup ./main -config conf/conf</span></span></code></pre></div><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Go%E8%BF%9B%E9%98%B6%C2%B7%E5%88%86%E5%B8%83%E5%BC%8F%E7%88%AC%E8%99%AB%E5%AE%9E%E6%88%98/images/41/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Go%E8%BF%9B%E9%98%B6%C2%B7%E5%88%86%E5%B8%83%E5%BC%8F%E7%88%AC%E8%99%AB%E5%AE%9E%E6%88%98/images/41/1.png" alt=""></a></p><p>通过打印出的日志我们发现，协程等待队列中基本没有等待运行的协程，这从侧面证明，当前程序有极大的 QPS 提升空间。这个现象也解释了为什么在压测情况下 cpu idle 仍然很高，因为程序没有满负载运行。</p><p>我们使用 trace 工具进行分析，能够更直观地分析出程序负载不足的情况。瞬时可运行协程数量小于逻辑处理器 P 的数量，并且 P 运行协程有大量的间隙。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Go%E8%BF%9B%E9%98%B6%C2%B7%E5%88%86%E5%B8%83%E5%BC%8F%E7%88%AC%E8%99%AB%E5%AE%9E%E6%88%98/images/41/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Go%E8%BF%9B%E9%98%B6%C2%B7%E5%88%86%E5%B8%83%E5%BC%8F%E7%88%AC%E8%99%AB%E5%AE%9E%E6%88%98/images/41/2.png" alt=""></a></p><h3 id="请求消耗过多-cpu-的问题" tabindex="-1">请求消耗过多 CPU 的问题 <a class="header-anchor" href="#请求消耗过多-cpu-的问题" aria-label="Permalink to &quot;请求消耗过多 CPU 的问题&quot;">​</a></h3><p>在压测时，我们收集了 pprof 火焰图，并把它和正常负载下的火焰图进行了对比，没有发现明显变化。</p><h3 id="并发导致的锁问题" tabindex="-1">并发导致的锁问题 <a class="header-anchor" href="#并发导致的锁问题" aria-label="Permalink to &quot;并发导致的锁问题&quot;">​</a></h3><p>在高并发场景下，如果程序都在争抢同一把锁，那么有可能会产生协程等待，导致耗时变长的问题。</p><p>但是从代码上来看，我们当前分析的程序几乎未使用锁等同步机制。另一方面，即便是使用锁，在如此低的负载情况下，也几乎不可能出现几百毫秒的延迟，更不要提标准库中的锁耗时，都要上万 QPS 才可能导致瓶颈问题。</p><p>查看 pprof block，也没有发现瓶颈问题。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>go tool pprof http://localhost:9981/debug/pprof/block</span></span>
<span class="line"><span>go tool pprof http://localhost:9981/debug/pprof/mutex</span></span></code></pre></div><h3 id="同步写日志的磁盘问题" tabindex="-1">同步写日志的磁盘问题 <a class="header-anchor" href="#同步写日志的磁盘问题" aria-label="Permalink to &quot;同步写日志的磁盘问题&quot;">​</a></h3><p>在 Go 程序中，磁盘 IO 并没有像网络一样，可以使用多路复用的机制。这意味着协程可能会陷入到操作系统调用中。这也是我们之前想要去查看线程数量的原因。因为长时间陷入到操作系统调用时，sysmon 监控程序会创建新的线程。但是线程数量是比较正常的，同时查看下面磁盘的一些核心指标没有发现异常：</p><ul><li><p>磁盘容量正常</p></li><li><p>磁盘利用率正常</p></li><li><p>inode 利用率正常</p></li><li><p>iops 正常</p></li><li><p>磁盘输入 / 输出操作时间占比正常</p></li></ul><h3 id="垃圾回收问题" tabindex="-1">垃圾回收问题 <a class="header-anchor" href="#垃圾回收问题" aria-label="Permalink to &quot;垃圾回收问题&quot;">​</a></h3><p>接着往下想，会不会是垃圾回收的问题？</p><p>当前程序 GC 频率相对较高，在压测时能够达到几秒一次，但是初步分析不足以导致瓶颈。从程序暴露的运行时指标来看，GC 程序生命周期内，平均花费的 CPU 时间在千分之二左右，STW 时间（即不可用时间）小于 1 毫秒，这些信息都表明 GC 不是瓶颈。</p><h3 id="宿主机问题" tabindex="-1">宿主机问题 <a class="header-anchor" href="#宿主机问题" aria-label="Permalink to &quot;宿主机问题&quot;">​</a></h3><p>我们再来看看宿主机，由于我们现在的程序运行在容器中，虽然理论上资源是完全隔离的，但是现在宿主机的问题仍然可能影响到容器。我们需要依次查看下面这些指标。</p><ul><li><p>宿主机 cpu idle 正常。</p></li><li><p>CPU 外部争抢 cpu.exter_wait_rate 正常，这个指标主要用来衡量任务在线程等待队列中等待时，等待其他容器的时间是否过长，这是我们公司内部自己的指标。</p></li><li><p>Cgroup CPU 与内存设置正常。</p></li><li><p>查看容器 cpu.throttled 和 throttled_time，发现它们在正常情况下和压测时都会存在。这个指标可以判断是否存在资源抢占导致的耗时增加。如果容器的资源被利用得太狠，到达了分配的资源限制，就可能出现这样的情况。但是压测时数据没有明显的飙升，不足以导致耗时增加 300 毫秒。</p></li><li><p>查看一段时间内操作系统线程堆栈，发现程序大部分时间并没有耗在操作系统调用上，而是在用户态上。</p></li></ul><p>总之，从现象上看，这个问题和宿主机有关系，但直接对宿主机进行分析无法得出清晰的结论。</p><h3 id="以退为进分析法" tabindex="-1">“以退为进分析法” <a class="header-anchor" href="#以退为进分析法" aria-label="Permalink to &quot;“以退为进分析法”&quot;">​</a></h3><p>分析到这里，问题似乎陷入了僵局。不得已，我们需要以退为进，回归到最原始的问题，来分析耗时是陷入到了哪里。</p><p>我们直接在代码的关键位置打印出耗时，分析耗时高的程序到底把时间消耗在了哪里。</p><p>通过对日志的分析，我们发现，大部分时间都消耗在了 clone 函数上，其功能是对一个结构体进行深拷贝。程序中调用 clone 非常频繁，一次复杂的请求可能会调用 1000 次 clone 函数。但是我们打印每一次 clone 函数的时间，发现都不足 1 毫秒，只是累积起来就比较吓人了。也就是说，内存分配没有明显的突然的恶化导致的卡点，而是有一种情况让整体的内存分配耗时恶化了。</p><p>在深入分析运行时内存分配可能的 Bug 之前，我选择了使用更强大的工具 trace 分析程序在生命周期内的运行状态，这也让我最终找到了答案。trace 借助于 Go 运行时在关键时刻的埋点，帮助我们一窥程序的运行过程。</p><p>具体做法是，首先抓取压测情况下的 trace，然后分析 Goroutine analysis。Goroutineanalysis 是一个非常有用的工具，它可以分析单个协程的情况。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> trace.out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:9981/debug/pprof/trace?seconds=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">30</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tool</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> trace</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -http=localhost:8000</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  trace.out</span></span></code></pre></div><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Go%E8%BF%9B%E9%98%B6%C2%B7%E5%88%86%E5%B8%83%E5%BC%8F%E7%88%AC%E8%99%AB%E5%AE%9E%E6%88%98/images/41/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Go%E8%BF%9B%E9%98%B6%C2%B7%E5%88%86%E5%B8%83%E5%BC%8F%E7%88%AC%E8%99%AB%E5%AE%9E%E6%88%98/images/41/3.png" alt=""></a></p><p>我们要做的是，找到我们想要分析的那个函数对应的协程。如下所示，A.func6 是 A 函数的第6 个协程，样本数有五百多个。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Go%E8%BF%9B%E9%98%B6%C2%B7%E5%88%86%E5%B8%83%E5%BC%8F%E7%88%AC%E8%99%AB%E5%AE%9E%E6%88%98/images/41/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Go%E8%BF%9B%E9%98%B6%C2%B7%E5%88%86%E5%B8%83%E5%BC%8F%E7%88%AC%E8%99%AB%E5%AE%9E%E6%88%98/images/41/4.png" alt=""></a></p><p>接下来，分析一下这些样本协程的耗时情况。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Go%E8%BF%9B%E9%98%B6%C2%B7%E5%88%86%E5%B8%83%E5%BC%8F%E7%88%AC%E8%99%AB%E5%AE%9E%E6%88%98/images/41/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Go%E8%BF%9B%E9%98%B6%C2%B7%E5%88%86%E5%B8%83%E5%BC%8F%E7%88%AC%E8%99%AB%E5%AE%9E%E6%88%98/images/41/5.png" alt=""></a></p><p>从图中可以看出，一些协程的最大函数耗时超过了 300 毫秒，这些协程会导致 p99 的飙升，和现象是对应的。同时，点击耗时比较大的协程，可以看到协程的耗时花在了哪些地方。可以看到，协程的耗时主要花费在了 Execution 执行阶段，比较奇怪的是，这一阶段的大部分时间都处于 GC 阶段。</p><p>点击某一个协程的详细信息，可以看到协程在当前一段时间内的运行状态。等等，这密密麻麻的绿色线条是怎么回事，放大以后特别吓人，大部分时间都在 Mark Assisst。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Go%E8%BF%9B%E9%98%B6%C2%B7%E5%88%86%E5%B8%83%E5%BC%8F%E7%88%AC%E8%99%AB%E5%AE%9E%E6%88%98/images/41/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Go%E8%BF%9B%E9%98%B6%C2%B7%E5%88%86%E5%B8%83%E5%BC%8F%E7%88%AC%E8%99%AB%E5%AE%9E%E6%88%98/images/41/6.png" alt=""></a></p><p>也就是说，程序在已经 GC 的情况下，由于疯狂的内存分配导致的 Mark Assisst 问题非常严重，这也就解释了为什么只有负载上来了才会导致 P99 问题。</p><h2 id="进一步分析与修复问题" tabindex="-1">进一步分析与修复问题 <a class="header-anchor" href="#进一步分析与修复问题" aria-label="Permalink to &quot;进一步分析与修复问题&quot;">​</a></h2><p>再总结一下问题的根源就是：GC 阶段下，大量的内存分配导致了大量的辅助标记，加上 25%的专有 GC 处理占用了 2 个线程，程序运行状态会迅速恶化。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Go%E8%BF%9B%E9%98%B6%C2%B7%E5%88%86%E5%B8%83%E5%BC%8F%E7%88%AC%E8%99%AB%E5%AE%9E%E6%88%98/images/41/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Go%E8%BF%9B%E9%98%B6%C2%B7%E5%88%86%E5%B8%83%E5%BC%8F%E7%88%AC%E8%99%AB%E5%AE%9E%E6%88%98/images/41/7.png" alt=""></a></p><p>上一节课程我们就已经介绍过辅助标记。在并发标记阶段，扫描内存的同时，用户协程也会不断被分配内存，当用户协程的内存分配速度快到后台标记协程来不及扫描时，GC 标记阶段将永远不会结束。这样一来，GC 周期就无法完整，还会进一步造成内存泄漏。</p><p>为了解决这样的问题，Go1.5 引入了辅助标记算法。用户协程被分配了超过限度的内存，运行时不得不将协程暂停，并切换去执行辅助标记工作。而由于我们当前程序的特性会频繁地分配内存，超过了内存扫描的速度，导致协程执行一段时间后就不得不切换到辅助标记工作，这增加了协程运行的时间，并最终导致了 p99 耗时非常严重。</p><p>这个问题的根源是内存的频繁释放和分配。在实践中我们发现，频繁的内存分配导致的程序问题经常会出现。举一个例子，我遇到过一个由于内存分配不合理导致程序直接 OOM 的问题。容器的内存容量本身为 16G，但是当程序内存达到 8G 之后，下一次 GC 的目标内存到达了16G。在这段时间里，内存频繁分配，不到两分钟就上涨到了 16G，直接导致了程序的崩溃。Go 运行时本身有一个定时监控服务，每 2 分钟会强制触发一次 GC，但是程序的特性却导致不到 2 分钟就把内存打满了。</p><p>遇到这样的问题应该如何解决呢？</p><p>有两种思路。一种是减少内存的分配，在这个线上问题中，由于程序设计不合理，导致每一次请求都会对一个大对象进行深拷贝，因此我们需要思考如何结合程序的场景，减少不合理的内存拷贝。</p><p>另一种思路是构建内存池来复用内存。谈到内存池，很多人会想到 sync.Pool。确实，sync.Pool 的源码是比较值得学习的，Go 在其中进行了很多底层优化，包括为了防止内存泄露而采取的回收策略；对结构的设计可以防止 CPU 缓存伪共享；设计 Ring-Buffer 结构可以复用内存并提高 CPU 缓存效率，每一个 P 中会存储本地缓存方便并发时的无锁访问。如果有兴趣你可以再深入学习 sync.Pool 的源码，这里我就不详细解读了。</p><p>但是我们不能忽视的是，sync.Pool 还有一些陷阱。sync.Pool 是一个底层的缓存池接口，它没有内置清空对象中的数据，这就需要我们在 get 或 put 对象时，额外去做这件事，否则会出现脏数据。</p><p>我们举一个 sync.Pool 的最佳实践，这是一个 fmt 包中使用 sync.Pool 的例子。fmt 利用sync.Pool 缓存了 pp 结构体，在 pp 结构体中，有一个 buf 字节数据。fmt 调用结束时，会使用 free 方法将 buf 清空。p.buf = p.buf[:0] 利用切片的截取将 buf 清空，并且保留了切片的容量。这在清空数据的同时，复用了之前分配的内存。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>func (p *pp) free() {</span></span>
<span class="line"><span>  // See https://golang.org/issue/23199</span></span>
<span class="line"><span>  if cap(p.buf) &gt; 64&lt;&lt;10 {</span></span>
<span class="line"><span>     return</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>  p.buf = p.buf[:0]</span></span>
<span class="line"><span>  p.arg = nil</span></span>
<span class="line"><span>  p.value = reflect.Value{}</span></span>
<span class="line"><span>  p.wrappedErr = nil</span></span>
<span class="line"><span>  ppFree.Put(p)</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>不过 sync.Pool 不是万能的，它并不是在所有场景下都适用，甚至可能适得其反。例如，如果我们的数据大量存储在 Map 中，想用 sync.Pool 缓存 Map 就不太好。因为我们无法在对 Map进行清空操作的同时保持 Map 的容量。这时，我们常常要根据实际的场景，修改设计结构或者构造自己的缓存池。此外，如果在我们的场景中，操作对象时 get 多 put 少，那么也会大量地分配内存，起不到缓存的作用。而在 get 少 put 多的场景下，sync.Pool 还会加重 GC 的负担。所以我建议你在使用 sync.Pool 前，先认真分析一下自己的场景是否适合使用sync.Pool。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>这节课，我们讲了一个真实的线上性能分析的实战案例。</p><p>这一线上瓶颈的本质是内存使用的不合理。当 GC 被触发之后，在高负载的情况下，内存分配的速度超过了 GC 扫描的速度，导致一直在执行辅助标记，大大减慢了程序运行的速度。这一现象进一步导致调度延迟等各方面的问题。通过优化代码逻辑和复用内存分配，我们可以消除瓶颈，节约上千台容器。</p><p>程序的运行状态就像是一个黑盒，不同的指标可以在侧面反映程序的运行状态，不同的工具也可以反映相同的问题。所以在合适的时间使用合适的工具，将起到事半功倍的效果。</p><p>一个运行中的程序似乎总是缺乏“内省”的能力，而为了观察到程序的运行过程，trace 工具通过在关键事件处进行埋点来实现事件追踪的能力。这节课的案例证明，trace 工具在分析程序整体运行状态甚至是 P99 瓶颈问题时确实非常强大，它是性能分析甚至是启发式探索问题的利器。</p><p>不得不说，在容器化的趋势下，排查复杂问题变得更加困难了。很多时候我们面临的问题不只是语言层面的，而是所有程序都需要面对的。所以一定要有体系化的思考和强大的学习能力。</p><h2 id="课后题" tabindex="-1">课后题 <a class="header-anchor" href="#课后题" aria-label="Permalink to &quot;课后题&quot;">​</a></h2><p>学完这节课，请你思考下面这个问题。</p><p>对于一个复杂的性能问题，需要有综合的能力并具备一些分析的工具。以 CPU 和内存为例，你知道哪些排查工具？</p><p>欢迎你在留言区与我交流讨论，我们下节课见。</p>`,87)])])}const d=a(p,[["render",l]]);export{u as __pageData,d as default};
